settings.source:
function run(input) {
  try {
    const data = typeof input === "string" ? JSON.parse(input) : input;

    // Caso erro ou sem dados
    if (
      !data ||
      data.errors ||
      !data.data ||
      !data.data.get_person_credit ||
      !data.data.get_person_credit.items ||
      data.data.get_person_credit.items.length === 0
    ) {
      return false;
    }

    const item = data.data.get_person_credit.items[0];

    function formatCurrency(value) {
      if (value === null || value === undefined) return "R$ 0,00";

      const number = Number(value);

      return "R$ " + number
        .toFixed(2)
        .replace(".", ",")
        .replace(/\B(?=(\d{3})+(?!\d))/g, ".");
    }

    return {
      available: formatCurrency(item.available),
      credit_area: item.credit_area || "",
      consumed: formatCurrency(item.consumed),
      customer_shared_id: item.customer_shared_id || "",
      minimal_order_value: formatCurrency(item.minimal_order_value),
      overdue: formatCurrency(item.overdue),
      status: item.status || "",
      total: formatCurrency(item.total)
    };

  } catch (e) {
    return false;
  }
}

function run(input) {
    try {
        const data = typeof input === "string"
            ? JSON.parse(input)
            : input;

        const items =
            data &&
            data.data &&
            data.data.get_person_credit &&
            Array.isArray(data.data.get_person_credit.items)
                ? data.data.get_person_credit.items
                : [];

        if (items.length === 0) {
            return "[]";
        }

        const credito = items[0];

        let valorTotal = Number(credito.total);

        if (!isFinite(valorTotal)) {
            valorTotal = 0;
        }

        function formatarValor(valor) {
            let numero = Number(valor);

            if (!isFinite(numero)) {
                numero = 0;
            }

            return "R$ " + numero
                .toFixed(2)
                .replace(".", ",")
                .replace(/\B(?=(\d{3})+(?!\d))/g, ".");
        }

        function calcularPercentual(percentual) {
            return valorTotal * (percentual / 100);
        }

        const rows = [
            {
                title: "Aumento de 5%",
                description: formatarValor(calcularPercentual(5)),
                dados: true
            },
            {
                title: "Aumento de 10%",
                description: formatarValor(calcularPercentual(10)),
                dados: true
            },
            {
                title: "Aumento de 15%",
                description: formatarValor(calcularPercentual(15)),
                dados: true
            },
            {
                title: "Aumento de 20%",
                description: formatarValor(calcularPercentual(20)),
                dados: true
            },
            {
                title: "Manter limite",
                description: "Quero manter o meu limite atual",
                dados: true
            },
            {
                title: "Menu anterior",
                description: "Desejo voltar ao menu anterior",
                dados: true
            }
        ];

        return JSON.stringify(rows);

    } catch (e) {
        return "[]";
    }
}

