function run(input) {
    try {
        const data = typeof input === "string"
            ? JSON.parse(input)
            : input;

        const items =
            data &&
            data.data &&
            data.data.get_person_customer &&
            Array.isArray(data.data.get_person_customer.items)
                ? data.data.get_person_customer.items
                : [];

        if (items.length === 0) {
            return JSON.stringify({
                shared_id: "",
                cnpj: "",
                sales_organization: "",
                requester: "",
                distribution_center: "",
                distribution_channel: "",
                office_code: "",
                sales_region: ""
            });
        }

        const customer = items[0];

        const salesInformations =
            Array.isArray(customer.sales_informations)
                ? customer.sales_informations
                : [];

        const salesInfo =
            salesInformations.length > 0
                ? salesInformations[0]
                : {};

        const staffMembers =
            Array.isArray(salesInfo.staff_member_seller)
                ? salesInfo.staff_member_seller
                : [];

        const staffMember =
            staffMembers.length > 0
                ? staffMembers[0]
                : {};

        const documents =
            Array.isArray(customer.documents)
                ? customer.documents
                : [];

        const document =
            documents.length > 0
                ? documents[0]
                : {};

        const distribution =
            salesInfo.distribution || {};

        return JSON.stringify({
            shared_id: customer.shared_id || "",
            cnpj: document.document_id || "",
            sales_organization: salesInfo.organization_code || "",
            requester: staffMember.shared_id_person_staffmember || "",
            distribution_center: distribution.center || "",
            distribution_channel: distribution.channel || "",
            office_code: salesInfo.office_code || "",
            sales_region: salesInfo.sales_region || ""
        });

    } catch (e) {
        return JSON.stringify({
            shared_id: "",
            cnpj: "",
            sales_organization: "",
            requester: "",
            distribution_center: "",
            distribution_channel: "",
            office_code: "",
            sales_region: ""
        });
    }
}

