async function run(tokenInput, taxDocument, dataInicial, dataFinal) {
    try {

        // ==========================================
        // CONVERTER DATA PARA ISO
        // Entrada:
        // 05/21/2026 00:00:00
        //
        // Saída:
        // 2026-05-21T00:00:00
        // ==========================================

        function converterDataParaIso(valor) {

            if (!valor) {
                return "";
            }

            var texto = String(valor).trim();

            // Caso já esteja em formato ISO
            if (/^\d{4}-\d{2}-\d{2}T/.test(texto)) {
                return texto;
            }

            var match = texto.match(
                /^(\d{2})\/(\d{2})\/(\d{4})\s+(\d{2}):(\d{2}):(\d{2})$/
            );

            if (!match) {
                return "";
            }

            var mes = match[1];
            var dia = match[2];
            var ano = match[3];

            var hora = match[4];
            var minuto = match[5];
            var segundo = match[6];

            return (
                ano +
                "-" +
                mes +
                "-" +
                dia +
                "T" +
                hora +
                ":" +
                minuto +
                ":" +
                segundo
            );
        }


        var dataInicialIso =
            converterDataParaIso(dataInicial);

        var dataFinalIso =
            converterDataParaIso(dataFinal);


        if (!dataInicialIso || !dataFinalIso) {
            return JSON.stringify({
                etapa: "ERRO_DATA",
                dataInicialRecebida: dataInicial,
                dataFinalRecebida: dataFinal,
                dataInicialConvertida: dataInicialIso,
                dataFinalConvertida: dataFinalIso
            });
        }


        // ==========================================
        // TOKEN
        // ==========================================

        var tokenData = tokenInput;

        if (typeof tokenData === "string") {
            try {
                tokenData = JSON.parse(tokenData);
            } catch (e) {
                // mantém como string
            }
        }

        var accessToken = "";

        if (
            tokenData &&
            typeof tokenData === "object" &&
            tokenData.access_token
        ) {
            accessToken =
                String(tokenData.access_token);

        } else if (
            typeof tokenData === "string" &&
            tokenData.length > 20
        ) {
            accessToken = tokenData;
        }

        if (!accessToken) {
            return JSON.stringify({
                etapa: "ERRO_TOKEN",
                mensagem: "Access token não encontrado"
            });
        }


        // ==========================================
        // URL
        // ==========================================

        var url =
            "https://ygg-qas.brf.cloud/operation/order/search";


        // ==========================================
        // GRAPHQL
        // ==========================================

        var query =
            "query MyQuery {" +
            " get_orders(" +
            "   filters: {" +

            "     customer_document_number: [" +
                    JSON.stringify(String(taxDocument)) +
            "]" +

            "     created_date_initial: " +
                    JSON.stringify(dataInicialIso) +

            "     created_date_final: " +
                    JSON.stringify(dataFinalIso) +

            "     offset: 0" +
            "     limit: 50" +

            "   }" +

            "   partner_key: \"aa4e8c78-21cc-43b0-bde7-cc3aa0843d9a\"" +

            " ) {" +

            "   orders {" +
            "     created_date" +
            "     order_sap" +
            "     total" +

            "     customer {" +
            "       order_number" +
            "     }" +

            "     status_list {" +
            "       status" +
            "       updated_time" +
            "     }" +

            "   }" +

            " }" +
            "}";


        var body = {
            query: query,
            variables: {}
        };


        // ==========================================
        // REQUISIÇÃO
        // ==========================================

        var response =
            await request.fetchAsync(
                url,
                {
                    method: "POST",
                    headers: {
                        "Content-Type": "application/json",
                        "Authorization":
                            "Bearer " + accessToken
                    },
                    body: JSON.stringify(body)
                }
            );


        // ==========================================
        // ERRO HTTP
        // ==========================================

        if (!response || !response.success) {

            return JSON.stringify({
                etapa: "ERRO_HTTP",

                status:
                    response
                        ? response.status
                        : null,

                dataInicialOriginal:
                    dataInicial,

                dataFinalOriginal:
                    dataFinal,

                dataInicialEnviada:
                    dataInicialIso,

                dataFinalEnviada:
                    dataFinalIso,

                body:
                    response && response.body
                        ? String(response.body)
                            .substring(0, 1500)
                        : ""
            });
        }


        // ==========================================
        // RESPOSTA
        // ==========================================

        var data =
            await response.jsonAsync();


        if (data && data.errors) {

            return JSON.stringify({
                etapa: "ERRO_GRAPHQL",
                errors: data.errors
            });
        }


        var orders =
            data &&
            data.data &&
            data.data.get_orders &&
            Array.isArray(
                data.data.get_orders.orders
            )
                ? data.data.get_orders.orders
                : [];


        // ==========================================
        // FORMATAR DATA DO MENU
        // ==========================================

        function formatarData(dataIso) {

            if (!dataIso) {
                return "";
            }

            var texto =
                String(dataIso).substring(0, 10);

            var partes =
                texto.split("-");

            if (partes.length !== 3) {
                return "";
            }

            return (
                partes[2] +
                "/" +
                partes[1] +
                "/" +
                partes[0]
            );
        }


        // ==========================================
        // VALOR
        // ==========================================

        function formatarValor(valor) {

            var numero =
                Number(valor);

            if (!isFinite(numero)) {
                numero = 0;
            }

            return "R$ " +
                numero
                    .toFixed(2)
                    .replace(".", ",")
                    .replace(
                        /\B(?=(\d{3})+(?!\d))/g,
                        "."
                    );
        }


        // ==========================================
        // STATUS
        // ==========================================

        function traduzirStatus(status) {

            if (!status) {
                return "Sem status";
            }

            var statusNormalizado =
                String(status)
                    .trim()
                    .toLowerCase();

            var traducoes = {
                "pending": "Pendente",
                "created": "Criado",
                "released": "Liberado",
                "blocked": "Bloqueado",
                "error": "Erro",
                "reject": "Recusado",
                "refused": "Recusado",
                "updated order": "Pedido atualizado",
                "in shipment": "Em transporte",
                "on route": "Em rota",
                "conference ok": "Conferência OK",
                "delivered": "Entregue",
                "cancelled": "Cancelado",
                "canceled": "Cancelado",
                "processing": "Em processamento",
                "invoiced": "Faturado",
                "completed": "Concluído"
            };

            return (
                traducoes[statusNormalizado] ||
                status
            );
        }


        function obterStatusAtual(statusList) {

            if (
                !Array.isArray(statusList) ||
                statusList.length === 0
            ) {
                return {
                    status: "Sem status",
                    updated_time: null
                };
            }

            var lista =
                statusList.slice();

            lista.sort(function (a, b) {

                var dataA =
                    a && a.updated_time
                        ? Date.parse(a.updated_time)
                        : 0;

                var dataB =
                    b && b.updated_time
                        ? Date.parse(b.updated_time)
                        : 0;

                if (!isFinite(dataA)) {
                    dataA = 0;
                }

                if (!isFinite(dataB)) {
                    dataB = 0;
                }

                return dataB - dataA;
            });

            return lista[0];
        }


        // ==========================================
        // 6 PEDIDOS MAIS RECENTES
        // ==========================================

        var ultimosPedidos =
            orders
                .slice()
                .sort(function (a, b) {

                    var dataA =
                        a && a.created_date
