function run(input) { 
    try { 
        const data = typeof input === "string" 
            ? JSON.parse(input) 
            : input; 

        if (!data || !data.metadata) { 
            return ""; 
        } 

        const metadata = data.metadata; 

        // ID da opção selecionada pelo usuário 
        const selectedId = metadata["#wa.interactive.list.id"]; 

        // Conteúdo da mensagem original que continha a lista 
        const replyContent = metadata["#replyContent"]; 

        if (!selectedId || !replyContent) { 
            return ""; 
        } 

        const reply = typeof replyContent === "string" 
            ? JSON.parse(replyContent) 
            : replyContent; 

        const sections = 
            reply && 
            reply.inReplyTo && 
            reply.inReplyTo.value && 
            reply.inReplyTo.value.interactive && 
            reply.inReplyTo.value.interactive.action && 
            reply.inReplyTo.value.interactive.action.sections; 

        if (!Array.isArray(sections)) { 
            return ""; 
        } 

        let selectedRow = null; 

        // Procura a row cujo ID é o mesmo selecionado no WhatsApp 
        for (let i = 0; i < sections.length; i++) { 
            const rows = sections[i].rows; 

            if (!Array.isArray(rows)) { 
                continue; 
            } 

            for (let j = 0; j < rows.length; j++) { 
                if (String(rows[j].id) === String(selectedId)) { 
                    selectedRow = rows[j]; 
                    break; 
                } 
            } 

            if (selectedRow) { 
                break; 
            } 
        } 

        if (!selectedRow || !selectedRow.description) { 
            return ""; 
        } 

        // Exemplo: 
        // "01141713 | Em transporte | R$ 476,17" 
        const partes = String(selectedRow.description).split("|"); 

        if (partes.length === 0) { 
            return ""; 
        } 

        return partes[0].trim(); 

    } catch (e) { 
        return ""; 
    } 
}

async function run(tokenInput, pedidoSelecionado) {
    try {
        // ==========================================
        // TOKEN
        // ==========================================

        let tokenData = tokenInput;

        if (typeof tokenData === "string") {
            try {
                tokenData = JSON.parse(tokenData);
            } catch (e) {
                // mantém como string
            }
        }

        let accessToken = "";

        if (
            tokenData &&
            typeof tokenData === "object" &&
            tokenData.access_token
        ) {
            accessToken = String(tokenData.access_token);

        } else if (
            typeof tokenData === "string" &&
            tokenData.length > 20
        ) {
            accessToken = tokenData;
        }

        if (!accessToken) {
            return JSON.stringify({
                success: false,
                erro: "Token não encontrado"
            });
        }

        // ==========================================
        // PEDIDO
        // ==========================================

        let numeroPedido = pedidoSelecionado
            ? String(pedidoSelecionado).trim()
            : "";

        if (!numeroPedido) {
            return JSON.stringify({
                success: false,
                erro: "Pedido não informado"
            });
        }

        // ==========================================
        // URL
        // ==========================================

        let url =
            "https://ygg-qas.brf.cloud/operation/order/search";

        // ==========================================
        // QUERY
        //
        // Busca SOMENTE o pedido selecionado
        // e SOMENTE os campos necessários.
        // ==========================================

        let query =
            "query BuscarPedido {" +
            " get_orders(" +
            "   filters: {" +
            "     customer_order_number: [" +
                    JSON.stringify(numeroPedido) +
            "]" +
            "     offset: 0" +
            "     limit: 10" +
            "   }" +
            "   partner_key: \"aa4e8c78-21cc-43b0-bde7-cc3aa0843d9a\"" +
            " ) {" +
            "   orders {" +
            "     order_sap" +
            "     customer {" +
            "       document_number" +
            "       order_number" +
            "     }" +
            "     billing_documents {" +
            "       document_number" +
            "       ref_doc_nr" +
            "     }" +
            "   }" +
            " }" +
            "}";

        let response = await request.fetchAsync(
            url,
            {
                method: "POST",
                headers: {
                    "Content-Type": "application/json",
                    "Authorization": "Bearer " + accessToken
                },
                body: JSON.stringify({
                    query: query,
                    variables: {}
                })
            }
        );

        // ==========================================
        // HTTP
        // ==========================================

        if (!response || !response.success) {
            return JSON.stringify({
                success: false,
                erro: "Erro na consulta do pedido",
                status: response ? response.status : null,
                body:
                    response && response.body
                        ? String(response.body).substring(0, 1000)
                        : ""
            });
        }

        let data = await response.jsonAsync();

        // ==========================================
        // GRAPHQL
        // ==========================================

        if (data && data.errors) {
            return JSON.stringify({
                success: false,
                erro: "Erro GraphQL",
                detalhes: data.errors
            });
        }

        let pedidos =
            data &&
            data.data &&
            data.data.get_orders &&
            Array.isArray(data.data.get_orders.orders)
                ? data.data.get_orders.orders
                : [];

        if (pedidos.length === 0) {
            return JSON.stringify({
                success: false,
                erro: "Pedido não encontrado"
            });
        }

        let pedido = pedidos[0];

        let billingDocuments =
            Array.isArray(pedido.billing_documents)
                ? pedido.billing_documents
                : [];

        let documento =
            billingDocuments.length > 0
                ? billingDocuments[0]
                : null;

        // ==========================================
        // RETORNO
        // ==========================================

        return JSON.stringify({
            success: true,

            numeroPedido:
                pedido.customer &&
                pedido.customer.order_number
                    ? String(
                        pedido.customer.order_number
                      ).trim()
                    : numeroPedido,

            orderSap:
                pedido.order_sap
                    ? String(pedido.order_sap).trim()
                    : "",

            cnpj:
                pedido.customer &&
                pedido.customer.document_number
                    ? String(
                        pedido.customer.document_number
                      ).trim()
                    : "",

            possuiNF:
                billingDocuments.length > 0,

            numeroNF:
                documento &&
                documento.document_number
                    ? String(
                        documento.document_number
                      ).trim()
                    : "",

            refDocNr:
                documento &&
                documento.ref_doc_nr
                    ? String(
                        documento.ref_doc_nr
                      ).trim()
                    : ""
        });

    } catch (e) {
        return JSON.stringify({
            success: false,
            erro: String(e.message || e)
        });
    }
}

