function run(input) { 
    try { 
        const data = typeof input === "string" 
            ? JSON.parse(input) 
            : input; 

        const orders = 
            data && 
            data.data && 
            data.data.get_orders && 
            Array.isArray(data.data.get_orders.orders) 
                ? data.data.get_orders.orders 
                : []; 

        if (orders.length === 0) { 
            return JSON.stringify({ 
                numero_pedido: "", 
                status_pedido: "", 
                data_pedido: "", 
                turno: "", 
                valor_total: "", 
                forma_pagamento: "" 
            }); 
        } 

        const pedido = orders[0]; 

        function formatarData(dataIso) { 
            if (!dataIso) { 
                return ""; 
            } 

            const data = new Date(dataIso); 

            if (isNaN(data.getTime())) { 
                return ""; 
            } 

            const dia = String(data.getUTCDate()).padStart(2, "0"); 
            const mes = String(data.getUTCMonth() + 1).padStart(2, "0"); 
            const ano = data.getUTCFullYear(); 

            return dia + "/" + mes + "/" + ano; 
        } 

        function formatarValor(valor) { 
            const numero = Number(valor); 

            if (!isFinite(numero)) { 
                return ""; 
            } 

            return numero 
                .toFixed(2) 
                .replace(".", ",") 
                .replace(/\B(?=(\d{3})+(?!\d))/g, "."); 
        } 

        function traduzirStatus(status) { 
            if (!status) { 
                return ""; 
            } 

            const statusNormalizado = String(status) 
                .trim() 
                .toLowerCase(); 

            const traducoes = { 
                "pending": "Pendente", 
                "created": "Criado", 
                "released": "Liberado", 
                "allocated stock": "Estoque alocado", 
                "in shipment": "Em transporte", 
                "on route": "Em rota", 
                "conference ok": "Conferência OK", 
                "delivered": "Entregue", 
                "refused": "Recusado", 
                "cancelled": "Cancelado", 
                "canceled": "Cancelado", 
                "processing": "Em processamento", 
                "invoiced": "Faturado", 
                "completed": "Concluído",
                "updated order": "Pedido atualizado",
                "Blocked": "Bloqueado",
                "blocked": "Bloqueado"
            }; 

            return traducoes[statusNormalizado] || status; 
        } 

        function obterStatusAtual(statusList) { 
            if (!Array.isArray(statusList) || statusList.length === 0) { 
                return ""; 
            } 

            const ordenados = statusList 
                .slice() 
                .sort(function (a, b) { 
                    const dataA = new Date(a.updated_time || 0).getTime(); 
                    const dataB = new Date(b.updated_time || 0).getTime(); 

                    return dataB - dataA; 
                }); 

            return traduzirStatus(ordenados[0].status); 
        } 

        const numeroPedido = 
            pedido.customer && 
            pedido.customer.order_number 
                ? pedido.customer.order_number 
                : pedido.order_sap || ""; 

        const formaPagamento = 
            pedido.customer && 
            pedido.customer.payment_method 
                ? pedido.customer.payment_method 
                : ""; 

        return JSON.stringify({ 
            numero_pedido: numeroPedido, 
            status_pedido: obterStatusAtual(pedido.status_list), 
            data_pedido: formatarData(pedido.created_date), 
            turno: formatarData(pedido.delivery_date), 
            valor_total: formatarValor(pedido.total), 
            forma_pagamento: formaPagamento 
        }); 

    } catch (e) { 
        return JSON.stringify({ 
            numero_pedido: "", 
            status_pedido: "", 
            data_pedido: "", 
            turno: "", 
            valor_total: "", 
            forma_pagamento: "" 
        }); 
    } 
}

