        const limiteAtual = Number(items[0].total);

        if (!isFinite(limiteAtual)) {
            return "";
        }

        if (!opcao || !opcao.title) {
            return "";
        }

        const titulo = String(opcao.title).trim();

        // Extrai o percentual do título
        // Ex.: "Aumento de 5%" -> 5
        const match = titulo.match(/(\d+)\s*%/);

        if (!match) {
            return "";
        }

        const percentual = Number(match[1]);

        if (!isFinite(percentual) || percentual <= 0) {
            return "";
        }

        // Calcula o valor do aumento
        const valorAumento =
            limiteAtual * (percentual / 100);

        // Calcula o novo limite TOTAL
        const novoLimite =
            limiteAtual + valorAumento;

        // Formato esperado pela API:
        // 3465.00
        return novoLimite.toFixed(2);

    } catch (e) {
        return "";
    }
}

function run(statusSolicitarAumentoCredito, responseSolicitarAumentoCredito) {
    try {
        const status = Number(statusSolicitarAumentoCredito);

        // Valida o status HTTP da requisição
        if (status !== 200 && status !== 201 && status !== 204) {
            return status;
        }

        // 204 = sucesso sem conteúdo
        if (status === 204) {
            return "sucesso";
        }

        const response = typeof responseSolicitarAumentoCredito === "string"
            ? JSON.parse(responseSolicitarAumentoCredito)
            : responseSolicitarAumentoCredito;

        if (!response) {
            return "erro";
        }

        const statusCode = Number(response.status_code);

        // Valida status retornado no body
        if (
            statusCode !== 200 &&
            statusCode !== 201 &&
            statusCode !== 204
        ) {
            return statusCode || "erro";
        }

        // Valida estrutura da resposta positiva
        if (
            !response.data ||
            !response.data.shared_id ||
            !response.data.request_no
        ) {
            return "erro";
        }

        return "sucesso";

    } catch (e) {
        return "erro";
    }
}

