async function run(orderSap, sharedId) {
    try {

        // ============================
        // 1. Busca a Nota Fiscal
        // ============================

        const responseNota = await reqNotaFiscal(
            orderSap,
            sharedId
        );

        if (!responseNota || !responseNota.body) {
            return JSON.stringify({
                etapa: "NOTA_FISCAL",
                error: true,
                status: responseNota
                    ? responseNota.status
                    : 0,
                message: "API de nota fiscal não retornou body."
            });
        }


        // ============================
        // 2. Converte body para objeto
        // ============================

        let dadosNota;

        try {
            dadosNota = typeof responseNota.body === "string"
                ? JSON.parse(responseNota.body)
                : responseNota.body;
        } catch (e) {
            return JSON.stringify({
                etapa: "PARSE_NOTA_FISCAL",
                error: true,
                status: responseNota.status || 0,
                message: "Não foi possível converter a resposta da nota fiscal para JSON.",
                inicioResposta: String(responseNota.body).substring(0, 500)
            });
        }


        // ============================
        // 3. Valida Notas
        // ============================

        if (
            !dadosNota ||
            !Array.isArray(dadosNota.Notas) ||
            dadosNota.Notas.length === 0
        ) {
            return JSON.stringify({
                etapa: "VALIDACAO_NOTA_FISCAL",
                error: true,
                status: responseNota.status || 0,
                message: "A resposta da API não contém o array Notas.",
                propriedades: dadosNota && typeof dadosNota === "object"
                    ? Object.keys(dadosNota)
                    : [],
                inicioResposta: JSON.stringify(dadosNota).substring(0, 500)
            });
        }


        // ============================
        // 4. Monta exatamente o body
        // esperado pela API conversora
        // ============================

        const payload = {
            Notas: dadosNota.Notas
        };


        // ============================
        // 5. Envia para conversão
        // ============================

        const responseConverter = await reqConverter(payload);


        // ============================
        // 6. Retorna resposta
        // ============================

        if (responseConverter && responseConverter.body) {
            return responseConverter.body;
        }

        return JSON.stringify({
            etapa: "CONVERSAO",
            error: true,
            status: responseConverter
                ? responseConverter.status
                : 0,
            message: "API de conversão não retornou body."
        });

    } catch (e) {
        return JSON.stringify({
            etapa: "ERRO_SCRIPT",
            error: true,
            message: e && e.message
                ? e.message
                : String(e)
        });
    }
}

