async function run() {
    try {

        // =========================
        // FUNÇÕES AUXILIARES
        // =========================

        function formatarData(dataIso) {
            if (!dataIso) {
                return "";
            }

            try {
                // Ex:
                // 2026-07-08T13:30:06+00:00
                // ->
                // 08/07/2026

                var parteData = String(dataIso).substring(0, 10);
                var partes = parteData.split("-");

                if (partes.length !== 3) {
                    return "";
                }

                return partes[2] + "/" + partes[1] + "/" + partes[0];

            } catch (e) {
                return "";
            }
        }


        function formatarValor(valor) {
            var numero = Number(valor);

            if (!isFinite(numero)) {
                numero = 0;
            }

            return "R$ " + numero
                .toFixed(2)
                .replace(".", ",")
                .replace(/\B(?=(\d{3})+(?!\d))/g, ".");
        }


        function traduzirStatus(status) {
            if (!status) {
                return "Sem status";
            }

            var statusNormalizado = String(status)
                .trim()
                .toLowerCase();

            var traducoes = {
                "pending": "Pendente",
                "created": "Criado",
                "released": "Liberado",
                "blocked": "Bloqueado",
                "error": "Erro",
                "reject": "Recusado",
                "refused": "Recusado",
                "updated order": "Pedido atualizado",
                "in shipment": "Em transporte",
                "on route": "Em rota",
                "conference ok": "Conferência OK",
                "delivered": "Entregue",
                "cancelled": "Cancelado",
                "canceled": "Cancelado",
                "processing": "Em processamento",
                "invoiced": "Faturado",
                "completed": "Concluído"
            };

            return traducoes[statusNormalizado] || status;
        }


        function obterStatusAtual(statusList) {
            if (!Array.isArray(statusList) || statusList.length === 0) {
                return {
                    status: "Sem status",
                    updated_time: null
                };
            }

            var statusOrdenados = statusList
                .slice()
                .sort(function (a, b) {

                    var dataA = a && a.updated_time
                        ? Date.parse(a.updated_time)
                        : 0;

                    var dataB = b && b.updated_time
                        ? Date.parse(b.updated_time)
                        : 0;

                    if (!isFinite(dataA)) {
                        dataA = 0;
                    }

                    if (!isFinite(dataB)) {
                        dataB = 0;
                    }

                    return dataB - dataA;
                });

            return statusOrdenados[0];
        }


        function adicionarOpcoesFixas(rows) {

            rows.push(
                {
                    title: "Não encontrei",
                    description: "Não encontrei o meu pedido e preciso de ajuda",
                    dados: true
                },
                {
                    title: "Menu anterior",
                    description: "Desejo voltar ao menu anterior",
                    dados: true
                },
                {
                    title: "Menu inicial",
                    description: "Voltar para as opções principais de atendimento.",
                    dados: true
                },
                {
                    title: "Encerrar atendimento",
                    description: "Desejo encerrar essa conversa",
                    dados: true
                }
            );

            return rows;
        }


        // =========================
        // VALIDAÇÃO DAS ENTRADAS
        // =========================

        if (!yggUrlHMG || !accessToken || !taxDocument) {
            return JSON.stringify(
                adicionarOpcoesFixas([])
            );
        }


        var baseUrl = String(yggUrlHMG).trim();

        // Remove barra final caso exista
        baseUrl = baseUrl.replace(/\/+$/, "");

        var url =
            baseUrl +
            "/operation/order/search";


        // =========================
        // GRAPHQL
        // =========================
        //
        // Importante:
        // estamos trazendo SOMENTE os campos
        // necessários para montar o menu.
        //
        // Isso evita a resposta gigante e o REDUCED.
        // =========================

        var query =
            "query MyQuery {" +
            " get_orders(" +
            "   filters: {" +
            "     customer_document_number: [" + JSON.stringify(String(taxDocument)) + "]" +
            "     created_date_initial: " + JSON.stringify(String(dataInicial || "")) +
            "     created_date_final: " + JSON.stringify(String(dataFinal || "")) +
            "     offset: 0" +
            "     limit: 50" +
            "   }" +
            "   partner_key: \"aa4e8c78-21cc-43b0-bde7-cc3aa0843d9a\"" +
            " ) {" +
            "   orders {" +
            "     created_date" +
            "     order_sap" +
            "     total" +
            "     customer {" +
            "       order_number" +
            "     }" +
            "     status_list {" +
            "       status" +
            "       updated_time" +
            "     }" +
            "   }" +
            " }" +
            "}";


        var body = {
            query: query,
            variables: {}
        };


        // =========================
        // REQUISIÇÃO YGG
        // =========================

        var response = await request.fetchAsync(
            url,
            {
                method: "POST",
                headers: {
                    "Content-Type": "application/json",
                    "Authorization": "Bearer " + String(accessToken)
                },
                body: JSON.stringify(body)
            }
        );


        // =========================
        // VALIDAÇÃO HTTP
        // =========================

        if (!response || !response.success) {

            return JSON.stringify(
                adicionarOpcoesFixas([])
            );
        }


        // =========================
        // CONVERTE RESPOSTA
        // =========================

        var data = await response.jsonAsync();


        // =========================
        // VALIDAÇÃO GRAPHQL
        // =========================

        if (
            !data ||
            !data.data ||
            !data.data.get_orders ||
            !Array.isArray(data.data.get_orders.orders)
        ) {

            return JSON.stringify(
                adicionarOpcoesFixas([])
            );
        }


        var orders = data.data.get_orders.orders;


        // =========================
        // ORDENA PEDIDOS
        // =========================

        var ultimosPedidos = orders
            .slice()
            .sort(function (a, b) {

                var dataA = a && a.created_date
                    ? Date.parse(a.created_date)
                    : 0;

                var dataB = b && b.created_date
                    ? Date.parse(b.created_date)
                    : 0;

                if (!isFinite(dataA)) {
                    dataA = 0;
                }

                if (!isFinite(dataB)) {
                    dataB = 0;
                }

                return dataB - dataA;
            })
            .slice(0, 6);


        // =========================
        // MONTA MENU
        // =========================

        var rows = [];


        ultimosPedidos.forEach(function (pedido) {

            var statusAtual =
                obterStatusAtual(pedido.status_list);


            var numeroPedido = "";

            if (
                pedido.customer &&
                pedido.customer.order_number
            ) {

                numeroPedido =
                    pedido.customer.order_number;

            } else if (pedido.order_sap) {

                numeroPedido =
                    pedido.order_sap;

            } else {

                numeroPedido =
                    "Sem número";
            }


            var statusTraduzido =
                traduzirStatus(statusAtual.status);


            var dataPedido =
                formatarData(pedido.created_date);


            var total =
                formatarValor(pedido.total);


            rows.push({
                title: dataPedido,
                description:
                    numeroPedido +
                    " | " +
                    statusTraduzido +
                    " | " +
                    total,
                dados: true
            });

        });


        // =========================
        // OPÇÕES FIXAS
        // =========================

        adicionarOpcoesFixas(rows);


        // =========================
        // RETORNO FINAL
        // =========================

        return JSON.stringify(rows);


    } catch (e) {

        return JSON.stringify([
            {
                title: "Não encontrei",
                description: "Não encontrei o meu pedido e preciso de ajuda",
                dados: true
            },
            {
                title: "Menu anterior",
                description: "Desejo voltar ao menu anterior",
                dados: true
            },
            {
                title: "Menu inicial",
                description: "Voltar para as opções principais de atendimento.",
                dados: true
            },
            {
                title: "Encerrar atendimento",
                description: "Desejo encerrar essa conversa",
                dados: true
            }
        ]);
    }
}

function run(input) {
    try {
        var rows = typeof input === "string"
            ? JSON.parse(input)
            : input;

        if (!Array.isArray(rows) || rows.length === 0) {
            return false;
        }

        // Considera somente os 6 primeiros itens
        var primeirosSeis = rows.slice(0, 6);

        // Formato esperado do title dos pedidos: dd/mm/aaaa
        var regexData = /^\d{2}\/\d{2}\/\d{4}$/;

        // Retorna true se pelo menos um dos 6 primeiros for um pedido
        return primeirosSeis.some(function (item) {
            return item &&
                item.title &&
                regexData.test(String(item.title).trim());
        });

    } catch (e) {
        return false;
    }
}

